import * as THREE from 'https://cdn.jsdelivr.net/npm/three@0.160.0/build/three.module.js';

(() => {
  const $ = id => document.getElementById(id);
  const canvas = $('game');
  const renderer = new THREE.WebGLRenderer({canvas, antialias:true, alpha:false, powerPreference:'high-performance'});
  renderer.setPixelRatio(Math.min(devicePixelRatio || 1, 1.7));
  renderer.setSize(innerWidth, innerHeight);
  renderer.shadowMap.enabled = true;
  renderer.shadowMap.type = THREE.PCFSoftShadowMap;
  renderer.outputColorSpace = THREE.SRGBColorSpace;
  renderer.toneMapping = THREE.ACESFilmicToneMapping;
  renderer.toneMappingExposure = 1.18;
  const scene = new THREE.Scene();
  scene.background = new THREE.Color('#91c9ef');
  scene.fog = new THREE.Fog('#b9d8f3', 44, 115);
  const camera = new THREE.PerspectiveCamera(76, innerWidth/innerHeight, .08, 180);
  camera.rotation.order = 'YXZ';
  const hemi = new THREE.HemisphereLight(0xc9e6ff, 0x4f6481, 2.15); scene.add(hemi);
  const sun = new THREE.DirectionalLight(0xffdfad, 3.25); sun.position.set(-18,30,-12); sun.castShadow=true; sun.shadow.mapSize.set(1536,1536); sun.shadow.camera.left=-32; sun.shadow.camera.right=32; sun.shadow.camera.top=32; sun.shadow.camera.bottom=-32; sun.shadow.bias=-.0003; scene.add(sun);
  const fill = new THREE.DirectionalLight(0x86baff, 1.2); fill.position.set(18,12,16); scene.add(fill);
  const mat=(color,roughness=.72,metalness=0,emissive=null,intensity=0)=>new THREE.MeshStandardMaterial({color,roughness,metalness,emissive:emissive||color,emissiveIntensity:intensity});
  const mats={grass:mat('#60b882'),grass2:mat('#72c78f'),stone:mat('#b4b1ce'),edge:mat('#77799d'),gold:mat('#f3c779',.37,.35),wood:mat('#a97858'),leaf:mat('#48a77f'),white:mat('#f6f2e9'),cloud:mat('#fff9ff',.94),crystal:mat('#82eaff',.25,.1,'#43cfff',1.2),purple:mat('#ae83ff',.25,.12,'#8e57ff',1.1)};
  const world={solids:[], enemies:[], shots:[], particles:[], pickups:[], clouds:[], running:false,paused:false,ended:false,started:false,clock:new THREE.Clock(),time:0,kills:0,total:6,toastTimer:0,hitTimer:0,aimYaw:0,aimPitch:0,sound:true,audio:null};
  const player={pos:new THREE.Vector3(0,1.7,11),vel:new THREE.Vector3(),grounded:true,jumps:0,health:100,mana:100,shield:0,shieldCd:0,boltCd:0,burstCd:0,dashCd:0,dashing:0,invuln:0,step:0,bob:0};
  const sphereGeo=new THREE.SphereGeometry(1,16,12), boxGeo=new THREE.BoxGeometry(1,1,1), cylGeo=new THREE.CylinderGeometry(1,1,1,12), crystalGeo=new THREE.OctahedronGeometry(1,0);
  const v=(x,y,z)=>new THREE.Vector3(x,y,z);
  function mesh(geo,material,x,y,z,sx=1,sy=1,sz=1,parent=scene){const o=new THREE.Mesh(geo,material);o.position.set(x,y,z);o.scale.set(sx,sy,sz);o.castShadow=true;o.receiveShadow=true;parent.add(o);return o;}
  function addSolid(x,y,z,w,h,d,material,collide=true){const o=mesh(boxGeo,material,x,y,z,w,h,d);if(collide)world.solids.push({x,z,w,d,top:y+h/2,bottom:y-h/2,mesh:o});return o;}
  function cloudCluster(x,y,z,scale=1,color='#fff9ff',drift=0){const g=new THREE.Group();g.position.set(x,y,z);scene.add(g);const cm=mat(color,.96);for(let i=0;i<6;i++){const a=i*Math.PI*2/6;const p=mesh(sphereGeo,cm,Math.cos(a)*scale*.46,(i%2)*scale*.13,Math.sin(a)*scale*.28,scale*(.48+(i%3)*.07),scale*.38,scale*.42,g);p.castShadow=false;}const center=mesh(sphereGeo,cm,0,scale*.09,0,scale*.57,scale*.44,scale*.52,g);center.castShadow=false;world.clouds.push({group:g,x,y,z,drift,phase:Math.random()*6});}
  function makeArena(){
    scene.add(new THREE.Mesh(new THREE.SphereGeometry(120,32,20),new THREE.MeshBasicMaterial({color:'#8bc5ef',side:THREE.BackSide})));
