    // Colorful organized ground inlays
    const inlay=mat('#78ca91'); for(const [x,z,w,d] of [[0,0,11,11],[-12,-11,8,7],[12,-11,8,7],[-12,12,8,7],[12,12,8,7]]){
      const p=mesh(boxGeo,inlay,x,.005,z,w,.035,d);p.receiveShadow=true;
    }
    const stoneTile=mat('#b7c8ce');
    for(let i=0;i<10;i++){const a=i*Math.PI/5;const x=Math.cos(a)*15,z=Math.sin(a)*15;mesh(cylGeo,stoneTile,x,.015,z,1.1,.07,1.1);}
    // Border rim; low rounded-looking guard walls keep players safely on the island.
    for(let i=-18;i<=18;i+=3){for(const [x,z,rot] of [[i,-19.5,0],[i,19.5,0],[-19.5,i,Math.PI/2],[19.5,i,Math.PI/2]]){const r=mesh(boxGeo,mats.gold,x,.48,z,2.4,.75,.22);r.rotation.y=rot;}}
    // Floating hop platforms, short steps and ornamental bridges
    const raised=[[-11,1.0,-7,5,1.05,4],[11,1.05,-7,5,1.15,4],[-11,.8,8,5,.9,4],[11,1.15,8,5,1.35,4]];
    raised.forEach(([x,y,z,w,h,d],i)=>{addSolid(x,y,z,w,h,d,i%2?mats.stone:mat('#d7ba88'));addSolid(x,y+h/2+.055,z,w-.25,.07,d-.25,i%2?mat('#a6e2bb'):mat('#d7c88d'),false);
