      const base=mesh(cylGeo,mats.stone,x,.38,z,.48,.76,.48);const gem=mesh(crystalGeo,mat(c,.24,.1,c,1.5),x,.95,z,.27,.68,.27);gem.rotation.y=.4;
      const light=new THREE.PointLight(c,1.1,5);light.position.set(x,1.5,z);scene.add(light);
      for(let j=0;j<3;j++){const rock=mesh(sphereGeo,mat(j%2?'#9a9bb5':'#c2afbd'),x+(j-1)*.55,.18,z+1.1,.38,.28,.32);rock.rotation.y=j;}
    }
    for(const [x,z] of [[-17,-14],[17,-14],[-17,14],[17,14],[-2,-16],[2,16]]){
      const trunk=mesh(cylGeo,mat('#906f70'),x,.7,z,.17,1.4,.17);trunk.rotation.z=.07;
      for(let i=0;i<3;i++){const leaf=mesh(sphereGeo,mat(['#55b788','#70c78d','#85d19a'][i]),x+(i-1)*.36,1.45+(i%2)*.25,z,.53,.42,.49);}
      for(let i=0;i<4;i++){const flower=mesh(sphereGeo,mat(i%2?'#f8c874':'#e5a5ff'),x+(Math.random()-.5)*1.3,.12,z+(Math.random()-.5)*1.1,.12,.1,.12);}
    }
    // Soft cloud islands below and far behind the arena, never intersecting the play view
    for(const [x,y,z,s] of [[-27,-4,-27,5],[25,-7,-24,7],[-30,-8,20,7],[29,-5,25,5],[-10,-11,35,8],[12,-12,-36,8],[-44,4,-3,9],[45,3,6,9]])cloudCluster(x,y,z,s,'#f8f6ff',.12);
    // Distant suspended islets provide scale
    for(let i=0;i<8;i++){const a=i*Math.PI/4,x=Math.cos(a)*34,z=Math.sin(a)*34;mesh(sphereGeo,mat('#a7b3d2'),x,-4,z,3.8,1.2,3.5).castShadow=false;cloudCluster(x,-2.8,z,2.4,'#eaf4ff',.07);}
    const sunDisc=mesh(sphereGeo,mat('#ffe0a2',.3,0,'#ffdc9b',.65),-32,21,-45,5,5,5);sunDisc.castShadow=false;
  }
  makeArena();

